// Acoustic candidates only: steady voiced vowels, never a lexical transcription.
export function voiceFeatures(samples,rate,progress=()=>{}){const sr=8000,step=160,size=320,total=Math.floor(samples.length*sr/rate),frames=[],frame=new Float32Array(size);for(let at=0;at+size<total;at+=step){let mean=0;for(let i=0;i<size;i++){const pos=(at+i)*rate/sr,a=Math.floor(pos),v=samples[a]*(1-(pos-a))+(samples[a+1]||0)*(pos-a);frame[i]=v;mean+=v;}mean/=size;let energy=0,changes=0;for(let i=0;i<size;i++){frame[i]-=mean;energy+=frame[i]**2;if(i&&frame[i]*frame[i-1]<0)changes++;}const rms=Math.sqrt(energy/size);let best=0,lagAt=0;if(rms>.0015)for(let lag=20;lag<=114;lag+=2){let sum=0,e1=0,e2=0;for(let j=0;j<size-lag;j+=2){const a=frame[j],b=frame[j+lag];sum+=a*b;e1+=a*a;e2+=b*b;}const corr=sum/Math.sqrt(e1*e2+1e-15);if(corr>best){best=corr;lagAt=lag;}}frames.push([at/sr,rms,best,lagAt?sr/lagAt:0,changes/size]);if(at%(step*1000)===0)progress(at/total);}return frames;}
export function hesitationCandidates(frames,sensitivity=55,minDuration=.5){const threshold=.9-sensitivity*.003,pitchTolerance=.10+sensitivity*.004,rmsTolerance=.30+sensitivity*.015,out=[];let group=[],gaps=0;function finish(){if(group.length){const start=group[0][0],end=group.at(-1)[0]+.04;if(end-start>=minDuration)out.push({start,end,confidence:Math.round(100*group.reduce((s,f)=>s+f[2],0)/group.length)});}group=[];gaps=0;}
for(const f of frames){const prev=group.at(-1),voiced=f[1]>.003&&f[2]>=threshold&&f[4]<.3,stable=!prev||(Math.abs(Math.log2(f[3]/prev[3]))<pitchTolerance&&Math.abs(Math.log(Math.max(.0001,f[1])/prev[1]))<rmsTolerance);if(voiced&&stable){group.push(f);gaps=0;}else if(group.length&&++gaps<=2)continue;else{finish();if(voiced)group.push(f);}}finish();return out;}
